ap=argparse.ArgumentParser();ap.add_argument('failed',type=Path);ap.add_argument('out',type=Path);a=ap.parse_args();report=json.loads((a.failed/'drc.json').read_text());assert len(report['unconnected_items'])==1;assert any('Pad 2 [GND] of Q7' in v['description'] for v in report['unconnected_items'][0]['items']);d=sx.loads((a.failed/'preview.kicad_pcb').read_text());q=next(f for f in nodes(d,'footprint') if any(p[1:3]==['Reference','Q7'] for p in nodes(f,'property')));pad=next(p for p in nodes(q,'pad') if p[1]=='2');net=first(pad,'net');assert net[2]=='GND';x,y=first(q,'at')[1:3];px,py=first(pad,'at')[1:3];start=[x+px,y+py];end=[start[0],round(start[1]+.9,4)];d += [sx.loads(f'(segment (start {start[0]} {start[1]}) (end {end[0]} {end[1]}) (width 0.2) (layer "F.Cu") (net {net[1]}) (uuid "{uuid.uuid4()}"))'),sx.loads(f'(via (at {end[0]} {end[1]}) (size 0.6) (drill 0.3) (layers "F.Cu" "B.Cu") (net {net[1]}) (uuid "{uuid.uuid4()}"))')];a.out.mkdir();(a.out/'pcbgolf.kicad_pcb').write_text(sx.dumps(d));action=json.loads((a.failed/'request.json').read_text())['action'];action.update(kind='targeted_ground_via_escape',rationale='Router and native DRC both identify isolated Q7.2 ground. Seed a0.2mm front trace to a0.60/0.30mm through via0.9mm below that pad, then route every net and independently check all physical/electrical gates.',seed_copper={'net':'GND','pad':'Q7.2','trace':{'start':start,'end':end,'width':.2,'layer':'F.Cu'},'via':{'at':end,'diameter':.6,'drill':.3,'layers':['F.Cu','B.Cu']}},diagnostic_sha256=sha(a.failed/'drc.json'));write(a.out/'proposal.json',action)
